import{_ as i,o as a,c as t,ap as r,au as n}from"./chunks/framework.Dm5l0oAM.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"permalink":"/docs/getting-started/architecture/"},"headers":[],"relativePath":"docs/getting-started/architecture.md","filePath":"docs/getting-started/architecture.md"}'),o={name:"docs/getting-started/architecture.md"};function l(s,e,c,d,m,f){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h1><p>The architecture of the Service Lifecycle Management consists of serveral components:</p><p><img src="'+n+'" alt="Architecture" data-zoomable="true"></p><h2 id="discovery-server" tabindex="-1">Discovery Server <a class="header-anchor" href="#discovery-server" aria-label="Permalink to “Discovery Server”">​</a></h2><p>As <code>Discovery Server</code> <a href="https://www.consul.io" target="_blank" rel="noreferrer">Consul</a> from HashiCorp is used. It provides the following functionalities:</p><ul><li>List resources</li><li>List services</li><li>List backend components</li><li>Health monitoring of backend components</li></ul><h2 id="config-server" tabindex="-1">Config Server <a class="header-anchor" href="#config-server" aria-label="Permalink to “Config Server”">​</a></h2><p>As <code>Config Server</code> <a href="https://www.consul.io" target="_blank" rel="noreferrer">Consul</a> KV value store is used. It provides the following functionalities:</p><ul><li>Central provisioning of runtime configuration</li><li>Distribution of service configuration</li></ul><h2 id="credential-manager" tabindex="-1">Credential Manager <a class="header-anchor" href="#credential-manager" aria-label="Permalink to “Credential Manager”">​</a></h2><p>As <code>Credential Manager</code> <a href="https://www.vaultproject.io" target="_blank" rel="noreferrer">Vault</a> from HashiCrop is used. It provides the following functionalities: Provided functionalities:</p><ul><li>Management of SSH credentials</li><li>PKI certificate authority</li><li>Docker registry credentials</li><li>Service credentials</li></ul><h2 id="configuration-manager" tabindex="-1">Configuration Manager <a class="header-anchor" href="#configuration-manager" aria-label="Permalink to “Configuration Manager”">​</a></h2><p>As <code>Configuration manager</code> <a href="https://github.com/ansible/awx" target="_blank" rel="noreferrer">AWX</a> from ReaHat is used. It provides the following functionalities: Provided functionalities:</p><ul><li>Setup of Deployment Capabilites</li><li>Deployment of services</li></ul><h2 id="identity-and-access-management" tabindex="-1">Identity and Access Management <a class="header-anchor" href="#identity-and-access-management" aria-label="Permalink to “Identity and Access Management”">​</a></h2><p>For <code>Identity and Access Management</code> <a href="https://www.keycloak.org" target="_blank" rel="noreferrer">Keycloak</a> is used. It provides the following functionalities: Provided functionalities:</p><ul><li>User Management</li><li>Access Control</li><li>Permissions and role Management</li></ul><h2 id="message-queue" tabindex="-1">Message Queue <a class="header-anchor" href="#message-queue" aria-label="Permalink to “Message Queue”">​</a></h2><p>As <code>Message Queue</code> <a href="https://www.rabbitmq.com" target="_blank" rel="noreferrer">RabbitMQ</a> is used. It provides the following functionalities:</p><ul><li>Asynchronous communication between backend components</li><li>Reliable distribution of events and messages</li></ul><h2 id="service-management" tabindex="-1">Service Management <a class="header-anchor" href="#service-management" aria-label="Permalink to “Service Management”">​</a></h2><p>The <code>Service Management</code> is a custom implementation. It provides the following functionalities: Provided functionalities:</p><ul><li>Catalog of service offerings</li><li>Orchestration of service (un)deployments</li></ul><h2 id="resource-management" tabindex="-1">Resource Management <a class="header-anchor" href="#resource-management" aria-label="Permalink to “Resource Management”">​</a></h2><p>The <code>Resource Management</code> is a custom implementation. It provides the following functionalities:</p><ul><li>Discovery of resources</li><li>Management of resources</li><li>Management of Deployment Capabilites</li><li>Firmware update of resources</li></ul><h2 id="platform-management" tabindex="-1">Platform Management <a class="header-anchor" href="#platform-management" aria-label="Permalink to “Platform Management”">​</a></h2><p>The <code>Platform Management</code> is a custom implementation. It provides the following functionalities:</p><ul><li>Management of users</li><li>Coordination of user provisioning</li><li>Management of credential metadata and links</li></ul><h2 id="notification-service" tabindex="-1">Notification Service <a class="header-anchor" href="#notification-service" aria-label="Permalink to “Notification Service”">​</a></h2><p>The <code>Notification Service</code> is a custom implementation. It provides the following functionalities:</p><ul><li>Delivery of notifications for platform events</li><li>Distribution of user-relevant status information</li></ul><h2 id="information-service" tabindex="-1">Information Service <a class="header-anchor" href="#information-service" aria-label="Permalink to “Information Service”">​</a></h2><p>The <code>Information Service</code> is a custom implementation. It provides the following functionalities:</p><ul><li>Provision of aggregated platform information</li><li>Read-oriented access to system information</li></ul><h2 id="ui" tabindex="-1">UI <a class="header-anchor" href="#ui" aria-label="Permalink to “UI”">​</a></h2><p>The <code>UI</code> is a custom implementation. It provides the following functionalities:</p><ul><li>User interface</li><li>Web-based</li></ul>',39)])])}const g=i(o,[["render",l]]);export{h as __pageData,g as default};
